() => {
  const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach(card => {
    const title = card.querySelector('span')?.textContent?.trim();
    const image = card.querySelector('img')?.alt || '';
    const ratingElement = card.querySelector('[id^="mntl-recipe-star-rating"]');
    let ratingValue = '';
    if (ratingElement) {
      const stars = ratingElement.querySelectorAll('svg');
      let filledCount = 0;
      let halfStar = false;
      stars.forEach(star => {
        const use = star.querySelector('use');
        if (use) {
          const href = use.getAttribute('href') || use.getAttribute('xlink:href') || '';
          if (href.includes('star-filled')) filledCount++;
          else if (href.includes('star-half')) halfStar = true;
        }
      });
      ratingValue = halfStar ? (filledCount + 0.5) : filledCount;
    }
    const ratingsCount = card.querySelector('[id^="mntl-recipe-card-meta"] div')?.textContent?.trim();
    results.push({title, image, rating: ratingValue, ratingsCount});
  });
  return results;
}

