const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  const title = card.querySelector('.mntl-card-list-card__title')?.textContent?.trim() || '';
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
  let ratingValue = null;
  if (ratingContainer) {
    const ratingText = ratingContainer.getAttribute('aria-label') || '';
    const match = ratingText.match(/(\d+\.?\d*)/);
    if (match) ratingValue = parseFloat(match[1]);
  }
  const metaContainer = card.querySelector('[id^="mntl-recipe-card-meta"]');
  const ratingsCount = metaContainer ? metaContainer.textContent.replace(/\s+/g, ' ').trim() : '';
  results.push({title, rating: ratingValue, ratingsCount});
}
return JSON.stringify(results);

const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  // Get the entire text content of the card
  const text = card.textContent.replace(/\s+/g, ' ').trim();
  // Get all SVG stars
  const stars = card.querySelectorAll('[id^="mntl-recipe-star-rating"] svg');
  const starInfo = [];
  for (const star of stars) {
    const cls = star.getAttribute('class') || '';
    const html = star.innerHTML.substring(0, 200);
    const fill = star.querySelector('path')?.getAttribute('fill') || star.querySelector('polygon')?.getAttribute('fill') || '';
    const style = star.getAttribute('style') || '';
    const aria = star.getAttribute('aria-label') || '';
    const use = star.querySelector('use');
    const useHref = use ? (use.getAttribute('href') || use.getAttribute('xlink:href') || '') : '';
    starInfo.push({cls, fill, style, aria, useHref, htmlStart: html});
  }
  results.push({text: text.substring(0, 200), starCount: stars.length, stars: starInfo});
}
return JSON.stringify(results, null, 2).substring(0, 4000);

const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  const titleEl = card.querySelector('span.card__title') || card.querySelector('.card__title') || card.querySelector('[class*="title"]');
  let title = '';
  for (const span of card.querySelectorAll('span')) {
    if (span.textContent.trim() && !span.textContent.includes('Save Recipe')) {
      title = span.textContent.trim();
      break;
    }
  }

  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
  let rating = 0;
  if (ratingContainer) {
    const stars = ratingContainer.querySelectorAll('svg');
    let filledCount = 0;
    let halfCount = 0;
    for (const star of stars) {
      const use = star.querySelector('use');
      const href = use ? (use.getAttribute('href') || use.getAttribute('xlink:href') || '') : '';
      if (href === '#icon-star') filledCount++;
      else if (href === '#icon-star-half') halfCount++;
    }
    rating = filledCount + (halfCount * 0.5);
  }

  const metaContainer = card.querySelector('[id^="mntl-recipe-card-meta"]');
  const ratingsCount = metaContainer ? metaContainer.textContent.replace(/\s+/g, ' ').trim() : '';

  const href = card.href;
  results.push({title, rating, ratingsCount, href});
}
return JSON.stringify(results, null, 2);

const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
