}
return JSON.stringify(results, null, 2);

const el = document.getElementById('mntl-directions__list_1-0') || document.querySelector('[id*="directions"]');
if (el) el.scrollIntoView({behavior: 'instant', block: 'start'});
return el ? 'scrolled to directions' : 'directions not found';

const headings = document.querySelectorAll('h2, h3, h4');
let dirHeading = null;
for (const h of headings) {
  if (h.textContent.trim() === 'Directions') {
    dirHeading = h;
    break;
  }
}
if (dirHeading) {
  const container = dirHeading.parentElement;
  const listItems = container.querySelectorAll('li');
  const directions = [];
  for (const li of listItems) {
    const text = li.textContent.replace(/\s+/g, ' ').trim();
    if (text.length > 20) directions.push(text);
  }
  return JSON.stringify(directions, null, 2);
}
return 'Directions heading not found';
